def extract_log_data(log_line):
    """
    Extracts timestamp, status code, and request ID from an Nginx access log line.

    Format: $remote_addr - $remote_user [$time_local] "$request" $status $body_bytes_sent "$http_referer" "$http_user_agent" "$request_id"
    """
    # Robust regex using (?:\\.|[^"\\])* pattern for quoted strings to handle escaped quotes.
    # We capture all fields but will filter for output.
    regex = r'^[^ ]+ - [^ ]+ \[(?P<timestamp>\d{2}/(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)/\d{4}:\d{2}:\d{2}:\d{2} [+-]\d{4})\] "(?P<request>(?:\\.|[^"\\])*)" (?P<status>[1-5]\d{2}) (?P<bytes>\d+) "(?P<referer>(?:\\.|[^"\\])*)" "(?P<agent>(?:\\.|[^"\\])*)" "(?P<request_id>(?:\\.|[^"\\])*)"'

    match = re.match(regex, log_line)
    if match:
        return match.groupdict()
    return None

def process_logs(input_stream, output_format='tsv'):
    """Processes log lines from the input stream and prints them in the specified format."""
    for line in input_stream:
        line = line.strip()
        if not line:
            continue
        data = extract_log_data(line)
        if data:
            # Filter for requested fields: timestamp, status, request_id
            output_fields = {k: data[k] for k in ['timestamp', 'status', 'request_id']}
            if output_format == 'json':
                print(json.dumps(output_fields))
            else:
                # TSV: timestamp, status, request_id
                print(f"{output_fields['timestamp']}\t{output_fields['status']}\t{output_fields['request_id']}")

def test():
    test_cases = [
        {
