            "expected": {"timestamp": "21/May/2026:10:05:00 +0000", "status": "404", "bytes": "567", "request_id": "a1b2c3d4", "request": "POST /api/v1/data HTTP/1.1", "referer": "https://referer.com", "agent": "Mozilla/5.0"}
